head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Radio > P > selectedIndex]<br/>컴포넌트가 렌더링된 후 선택될 아이템의 인덱스를 설정합니다.",
    "validation" : [
        "컴포넌트가 렌더링될때 선택될 아이템의 인덱스를 숫자로 설정합니다.",
        "값을 설정하지 않거나 -1, 없는 인덱스값으로 설정하면 렌더링될때 아이템이 선택되지 않습니다.",
        // "디자인 시 아이템을 정의하지 않았거나 바인딩 된 DataCollection 에 데이터가 로딩되어야 하는 경우는 selectedIndex 속성값이 적용되지 않습니다.",
        "컴포넌트가 렌더링 된 후에는 컴포넌트에 선택된 아이템의 인덱스값을 갖습니다.",
        "컴포넌트에 선택된 아이템이 없으면 -1 값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        selectedIndex : con_selectedIndex.getText(),        
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<xf:select1 ' + strNameSpace + ' ' + cList + ' appearance="full" style="width:150px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:gdl_radio">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:select1>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "radio",
        strTarget,
        grp_comp
    );
}



scwin.btn_getSelectedIndex_onclick = function (e) {
    let rtn = '';

    rtn = target1.getSelectedIndex();

    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex : " + rtn);	
};
